#pragma once
#include <QObject>

class IssueModel;

// Keeps the sum of the estimates of the OPEN issues of a model. The sum follows
// each insert, remove, reset and data change of the model. totalChanged is emitted
// once for each change of the value, and never when the value stays the same.
// The summary does not own the model. After the model is destroyed, openMinutes() returns 0.
class BacklogSummary : public QObject
{
    Q_OBJECT
    Q_PROPERTY(int openMinutes READ openMinutes NOTIFY totalChanged)
public:
    explicit BacklogSummary(IssueModel *model, QObject *parent = nullptr);
    int openMinutes() const;

signals:
    void totalChanged(int minutes);

private:
    // Not implemented yet.
};

#include "estimate.h"
#include <QStringList>

int parseEstimate(const QString &text)
{
    const QStringList parts = text.split(' ', Qt::SkipEmptyParts);
    if (parts.isEmpty())
        return -1;
    int total = 0;
    for (const QString &part : parts) {
        if (part.size() < 2)
            return -1;
        const QString digits = part.left(part.size() - 1);
        const QChar unit = part.back();
        bool valid = true;
        for (const QChar c : digits)
            if (!c.isDigit()) {
                valid = false;
                break;
            }
        bool ok = false;
        const int value = digits.toInt(&ok);
        if (!valid || !ok || value < 0)
            return -1;
        switch (unit.unicode()) {
        case 'w': total += value * 5 * 24 * 60; break;
        case 'd': total += value * 24 * 60; break;
        case 'h': total += value * 60; break;
        case 'm': total += value; break;
        default: return -1;
        }
    }
    return total;
}

QString formatEstimate(int minutes)
{
    if (minutes < 0)
        return {};
    const int minutesPerDay = 8 * 60;
    const int minutesPerWeek = 5 * minutesPerDay;
    QStringList out;
    const int weeks = minutes / minutesPerWeek;
    int rem = minutes % minutesPerWeek;
    const int days = rem / minutesPerDay;
    rem %= minutesPerDay;
    const int hours = rem / 60;
    const int mins = rem % 60;
    if (weeks)
        out << QString::number(weeks) + "w";
    if (days)
        out << QString::number(days) + "d";
    if (hours)
        out << QString::number(hours) + "h";
    if (out.isEmpty() || mins)
        out << QString::number(mins) + "m";
    return out.join(' ');
}

